def backfill_teaching_assignment_periods(apps, schema_editor):
    TeachingAssignment = apps.get_model('home', 'TeachingAssignment')
    for assignment in TeachingAssignment.objects.select_related(
        'offering__class_group__academic_year'
    ).iterator():
        year = assignment.offering.class_group.academic_year
        starts = [
            getattr(year, f'q{quarter}_start') for quarter in range(1, 5)
            if getattr(year, f'q{quarter}_start') is not None
        ]
        ends = [
            getattr(year, f'q{quarter}_end') for quarter in range(1, 5)
            if getattr(year, f'q{quarter}_end') is not None
        ]
        if starts and ends:
            year_start = min(starts)
            year_end = max(ends)
        else:
            match = re.match(r'^\s*(\d{4})\D+(\d{4})', year.year or '')
            if match is None:
                raise RuntimeError(
                    f'AcademicYear #{year.pk} needs quarter boundaries or a '
                    'YYYY/YYYY label before TeachingAssignment periods can be '
                    'migrated.'
                )
            first_year, second_year = map(int, match.groups())
            year_start = datetime.date(first_year, 9, 1)
            year_end = datetime.date(second_year, 8, 31)

        assignment.start_date = year_start
        assignment.end_date = year_end if year.archived else None
        assignment.save(update_fields=['start_date', 'end_date'])


def clear_teaching_assignment_periods(apps, schema_editor):
    TeachingAssignment = apps.get_model('home', 'TeachingAssignment')
    TeachingAssignment.objects.update(start_date=None, end_date=None)


